class Solution:
    def isSubsequence(self, s: str, t: str) -> bool:
        sSet = set(s)
        t = list(t)
        lst = []
        for char in t:
            if char in sSet:
                lst.append(char)
        print(lst)
        str_lst = "".join(lst)
        print(str_lst)
        
        sMap = {}
        strMap = {}
        for i, char in enumerate(s):
            sMap[char] = i
        for i, char in enumerate(str_lst):
            strMap[char] = i
        print(sMap)
        print(strMap)
        for char in sMap:
            if char not in strMap or sMap[char] > strMap[char]:
                return False
        return True

def main():
    self = Solution()
    s = "axc"
    t = "ahbgdc"
    # t = ""
    print(Solution.isSubsequence(self, s, t))
main()